// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 caller1, uint256 caller2) public {
        vm.assume(caller1 != caller2);
        address actor1 = address(uint160(caller1));
        address actor2 = address(uint160(caller2));
        vm.assume(actor1 != address(0) && actor2 != address(0));
        vm.assume(actor1 != address(c) && actor2 != address(c));

        vm.deal(actor1, 10 ether);
        vm.deal(actor2, 10 ether);

        vm.prank(actor1);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        require(ok1, "first call must succeed");

        vm.prank(actor2);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        assertTrue(!ok2);
    }
}
